import json
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x = solver.IntVar(12, solver.infinity(), 'x')
    y = solver.IntVar(0, solver.infinity(), 'y')
    z = solver.IntVar(0, solver.infinity(), 'z')

    # Define constraints
    solver.Add(x + 2 * y + 3 * z <= 400)
    solver.Add(2 * x + 3 * y + 4 * z <= 300)
    solver.Add(3 * x + 4 * y + 5 * z <= 500)
    solver.Add(3 * z <= x + y)

    # Define objective function
    objective = solver.Objective()
    objective.SetMaximization()
    objective.SetCoefficient(x, 100)
    objective.SetCoefficient(y, 125)
    objective.SetCoefficient(z, 200)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = objective.Value()
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

