from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    S = solver.IntVar(0, solver.infinity(), 'small_boxes')
    L = solver.IntVar(5, solver.infinity(), 'large_boxes')

    # Define the objective function
    objective = solver.Objective()
    objective.SetMinimization()
    objective.SetCoefficient(S, 1)
    objective.SetCoefficient(L, 1)

    # Add constraints
    # Constraint 1: Total masks must be at least 750
    solver.Add(25 * S + 45 * L >= 750)

    # Constraint 2: Small boxes must be at least three times the large boxes
    solver.Add(S >= 3 * L)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_boxes = S.solution_value() + L.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_boxes
        }
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

