import json
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'x1')
    x2 = solver.IntVar(0, solver.infinity(), 'x2')
    x3 = solver.IntVar(0, solver.infinity(), 'x3')
    x4 = solver.IntVar(0, solver.infinity(), 'x4')

    # Define the objective function
    objective = solver.Objective()
    objective.SetMinimization()
    objective.SetCoefficient(x1, 10)
    objective.SetCoefficient(x2, 15)
    objective.SetCoefficient(x3, 20)
    objective.SetCoefficient(x4, 25)

    # Add constraints
    solver.Add(x1 + x2 <= 12)
    solver.Add(x3 + x4 <= 16)
    solver.Add(x1 + x3 >= 8)
    solver.Add(x2 + x4 >= 10)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_fatigue = 10 * x1.solution_value() + 15 * x2.solution_value() + 20 * x3.solution_value() + 25 * x4.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_fatigue
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

