    solver.Add(20 * G + 30 * E >= 150)

    # Constraint 2: 20G + 25E <= 140
    solver.Add(20 * G + 25 * E <= 140)

    # Constraint 3: E < G
    solver.Add(E <= G - 1)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
