    x = solver.IntVar(0, solver.infinity(), 'microwave_overs')
    y = solver.IntVar(0, solver.infinity(), 'water_heaters')

    # Objective function: Minimize total cost
    # Workshop A processing cost: 80*(2x + y)
    # Workshop B assembly cost: 20*(x + 3y)
    # Inspection and sales costs: 30x + 50y
    total_cost = 80 * (2 * x + y) + 20 * (x + 3 * y) + 30 * x + 50 * y
    solver.Minimize(total_cost)

    # Constraints
    # 1. Inspection and sales costs should not exceed 5500 yuan
    solver.Add(30 * x + 50 * y <= 5500)

    # 2. At least 80 microwave ovens should be sold
    solver.Add(x >= 80)

    # 3. Full utilization of workshop A
    solver.Add(2 * x + y == 250)

    # 4. Overtime in workshop A should not exceed 20 hours
    solver.Add(2 * x + y <= 270)

    # 5. At least 50 water heaters should be sold
    solver.Add(y >= 50)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = total_cost.solution_value()
