import math
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver("CBC_MIXED_INTEGER_PROGRAMMING")

    # Define decision variables
    w = solver.NumVar(0, 1.5, "width")
    h = solver.NumVar(0, 2, "height")
    x = solver.NumVar(0, (1.5)**2, "x")

    # Add constraint: x = w^2
    solver.Add(x == w * w)

    # Objective function: maximize w*h + 0.5 * 0.5 * π * x
    objective = solver.Objective()
    objective.SetMaximization()
    objective.SetCoefficient(w, 1)
    objective.SetCoefficient(h, 1)
    objective.SetCoefficient(x, 0.5 * 0.5 * math.pi)

    # Add constraints
    solver.Add(h + w / 2 <= 2)
    solver.Add(w <= 1.5)

    # Solve the problem
    status = solver.Solve()

    # Extract the optimal values
    optimal_w = w.solution_value()
    optimal_h = h.solution_value()
    optimal_x = x.solution_value()

    # Calculate the objective value
    objective_value = optimal_w * optimal_h + 0.5 * 0.5 * math.pi * optimal_x

    # Print the result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == "__main__":
    main()

