    # Define the facilities
    facilities = [1, 2, 3, 4]

    # Define decision variables
    L = {i: solver.IntVar(5, 30, f'L_{i}') for i in facilities}
    M = {i: solver.IntVar(3, 20, f'M_{i}') for i in facilities}

