        denominator = L[i].solution_value() + M[i].solution_value()
        total_efficiency += numerator / denominator

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_SOLVED",
        "objective_value": total_efficiency
    }

