import numpy as np
from ortools.linear_solver import pywraplp

# Define the cost matrix
cost_matrix = [
    [0, 87, 41, 55, 57],  # From City 1
    [87, 0, 80, 33, 40],  # From City 2
    [41, 80, 0, 90, 42],  # From City 3
    [55, 33, 90, 0, 53],  # From City 4
    [57, 40, 42, 53, 0]   # From City 5
]

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Number of cities
num_cities = 5

# Create binary variables for each possible edge
edges = {}
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            edges[(i, j)] = solver.IntVar(0, 1, f'edge_{i}_{j}')

# Objective function: minimize total travel cost
objective = solver.Objective()
for (i, j), var in edges.items():
    objective.SetCoefficient(var, cost_matrix[i][j])
objective.SetMinimization()

# Constraints: each city has exactly one outgoing and one incoming edge
for i in range(num_cities):
    outgoing_edges = sum(edges[(i, j)] for j in range(num_cities) if j != i)
    incoming_edges = sum(edges[(j, i)] for j in range(num_cities) if j != i)
    solver.Add(outgoing_edges == 1)
    solver.Add(incoming_edges == 1)

# Solve the problem
status = solver.Solve()

# Extract the optimal route
selected_edges = []
for (i, j), var in edges.items():
    if var.solution_value() > 0.5:
        selected_edges.append((i, j))

# Reconstruct the route
route = [0]  # Start from city 0
current_city = 0
for i in range(num_cities - 1):
    for j in range(num_cities):
        if (current_city, j) in selected_edges:
            route.append(j)
            current_city = j
            break

# Calculate total cost
total_cost = 0
for i in range(len(route) - 1):
    total_cost += cost_matrix[route[i]][route[i + 1]]

# Print the result
print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

