import numpy as np
from ortools.linear_solver import pywraplp

# Define the travel cost matrix
cost_matrix = [
    [0, 87, 41, 55, 57],  # City 1
    [87, 0, 80, 33, 40],  # City 2
    [41, 80, 0, 90, 42],  # City 3
    [55, 33, 90, 0, 53],  # City 4
    [57, 40, 42, 53, 0]   # City 5
]

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Number of cities
num_cities = 5

# Decision variables: x[i][j] is 1 if we travel from city i to city j, 0 otherwise
x = [[solver.IntVar(0, 1, f'x_{i}_{j}') for j in range(num_cities)] for i in range(num_cities)]

# Objective function: minimize total travel cost
objective = solver.Objective()
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            objective.SetCoefficient(x[i][j], cost_matrix[i][j])

# Constraint: each city is visited exactly once
for i in range(num_cities):
    solver.Add(solver.Sum([x[i][j] for j in range(num_cities) if i != j]) == 1)

# Constraint: each city is entered exactly once
for j in range(num_cities):
    solver.Add(solver.Sum([x[i][j] for i in range(num_cities) if i != j]) == 1)

# Solve the problem
status = solver.Solve()

# Extract the optimal tour
tour = []
for i in range(num_cities):
    for j in range(num_cities):
        if i != j and x[i][j].solution_value() > 0.5:
            tour.append((i, j))

# Calculate the total travel cost
total_cost = 0
for i, j in tour:
    total_cost += cost_matrix[i][j]

# Print the result
print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

