def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define the decision variable for radius r
    r = solver.NumVar(0.001, 100, 'r')

    # Objective function: 200 / r + 8r^2
    objective = solver.Objective()
    objective.SetMinimization()
    objective.SetCoefficient(r, 8)
    objective.SetCoefficient(1 / r, 200)

    # Solve the problem
    status = solver.Solve()

    # Extract the optimal radius
    optimal_r = r.solution_value()

    # Calculate the optimal height using the volume constraint
    optimal_h = 100 / (math.pi * optimal_r ** 2)

    # Calculate the total material used
    total_material = 2 * math.pi * optimal_r * optimal_h + 8 * optimal_r ** 2

    # Calculate the ratio of height to radius
    ratio = optimal_h / optimal_r

    # Prepare the result
    result = {
        "status": "OPTIMAL",
        "objective_value": total_material
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

