    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x = solver.NumVar(0, solver.infinity(), 'x')
    y = solver.NumVar(0, solver.infinity(), 'y')

    # Define the objective function
    # Since the volume is x^2 * y, we can express it as x * x * y
    # To linearize, we introduce a new variable V = x * x * y
    # However, since OR-Tools does not support nonlinear terms directly, we can use a substitution
    # Let's express the volume as x * (x * y)
    # We can introduce a new variable z = x * y
    z = solver.NumVar(0, solver.infinity(), 'z')
    solver.Add(z == x * y)

    # The volume is x * z
    volume = x * z

    # Define the constraint
    solver.Add(x * x + 4 * x * y <= 45)

    # Maximize the volume
    solver.Maximize(volume)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        x_value = x.solution_value()
        y_value = y.solution_value()
        z_value = z.solution_value()
        volume_value = x_value * z_value
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
