    solver.Add(20 * x + 15 * y <= 1200)
    # Eye cream constraint: 30x + 45y >= 1300
    solver.Add(30 * x + 45 * y >= 1300)
    # Foot cream constraint: 60x + 30y >= 1500
    solver.Add(60 * x + 30 * y >= 1500)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_time = x.solution_value() + y.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_time
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

