import json
import numpy as np
from ortools.linear_solver import pywraplp

# Define the time matrix
time_matrix = np.array([
    [3, 1, 1],
    [2, 1.5, 1],
    [3, 1.2, 1.3],
    [2, 2, 2],
    [2.1, 2, 3]
])

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Define variables
num_batches = 5
num_vats = 3
x = {}
for i in range(num_batches):
    for j in range(num_vats):
        x[(i, j)] = solver.IntVar(0, 1, f'x_{i}_{j}')

# Define completion times
C = [solver.NumVar(0, solver.infinity(), f'C_{j}') for j in range(num_vats)]

# Constraints: Each batch must be processed in all vats
for i in range(num_batches):
    solver.Add(solver.Sum([x[(i, j)] for j in range(num_vats)]) == 1)

# Constraints: Completion time of each vat
for j in range(num_vats):
    solver.Add(C[j] == solver.Sum([time_matrix[i][j] * x[(i, j)] for i in range(num_batches)]))

# Objective: Minimize the maximum completion time
max_C = solver.NumVar(0, solver.infinity(), 'max_C')
for j in range(num_vats):
    solver.Add(max_C >= C[j])

solver.Minimize(max_C)

# Solve the problem
status = solver.Solve()

# Extract the result
if status == pywraplp.Solver.OPTIMAL:
    objective_value = max_C.solution_value()
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
else:
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

